script:
frappe.ui.form.on("PH Montageauftrag", {
	refresh(frm) {
		if (frm.is_new()) return;
		frm.add_custom_button(__("Servicefall anlegen"), () => {
			frappe.prompt([
				{ fieldname: "art", fieldtype: "Select", label: __("Art"), options: ["Montagefehler", "Mangel", "Transportschaden"], default: "Montagefehler", reqd: 1 },
				{ fieldname: "fehlercode", fieldtype: "Link", options: "PH Fehlercode", label: __("Fehlercode") },
				{ fieldname: "beschreibung", fieldtype: "Small Text", label: __("Beschreibung"), reqd: 1 },
			], (v) => {
				frappe.call({ method: "ph_service.ph_service.doctype.ph_servicefall.ph_servicefall.aus_dokument", args: { doctype: frm.doctype, name: frm.doc.name, ...v }, freeze: true }).then((r) => {
					if (!r.message) return;
					const alt = frm.doc.ph_service_servicefaelle || "";
					frm.set_value("ph_service_servicefaelle", alt ? alt + ", " + r.message : r.message);
					frm.save().then(() => frappe.set_route("Form", "PH Servicefall", r.message));
				});
			}, __("Servicefall aus Montage"));
		}, __("Aktionen"));
	},
});

frappe.ui.form.on("PH Abnahme", {
	refresh(frm) {
		if (frm.is_new()) return;
		frm.add_custom_button(__("Servicefall anlegen"), () => {
			frappe.prompt([
				{ fieldname: "art", fieldtype: "Select", label: __("Art"), options: ["Mangel", "Montagefehler", "Transportschaden"], default: "Mangel", reqd: 1 },
				{ fieldname: "fehlercode", fieldtype: "Link", options: "PH Fehlercode", label: __("Fehlercode") },
				{ fieldname: "beschreibung", fieldtype: "Small Text", label: __("Mangel laut Abnahmeprotokoll"), reqd: 1 },
			], (v) => {
				frappe.call({ method: "ph_service.ph_service.doctype.ph_servicefall.ph_servicefall.aus_dokument", args: { doctype: frm.doctype, name: frm.doc.name, ...v }, freeze: true }).then((r) => r.message && frappe.set_route("Form", "PH Servicefall", r.message));
			}, __("Servicefall aus Abnahme"));
		}, __("Aktionen"));
	},
});

frappe.ui.form.on("PH Wareneingang", {
	refresh(frm) {
		if (frm.is_new() || frm.doc.ph_service_servicefall) {
			if (frm.doc.ph_service_servicefall) frm.add_custom_button(__("Servicefall öffnen"), () => frappe.set_route("Form", "PH Servicefall", frm.doc.ph_service_servicefall));
			return;
		}
		frm.add_custom_button(__("Servicefall anlegen (Transportschaden)"), () => {
			frappe.prompt([
				{ fieldname: "produkt", fieldtype: "Link", options: "PH Produkt", label: __("Produkt") },
				{ fieldname: "fehlercode", fieldtype: "Link", options: "PH Fehlercode", label: __("Fehlercode"), default: "TRA-01" },
				{ fieldname: "beschreibung", fieldtype: "Small Text", label: __("Schaden / Abweichung"), reqd: 1 },
			], (v) => {
				frappe.call({ method: "ph_service.ph_service.doctype.ph_servicefall.ph_servicefall.aus_dokument", args: { doctype: frm.doctype, name: frm.doc.name, art: "Transportschaden", ...v }, freeze: true }).then((r) => {
					if (!r.message) return;
					frappe.db.set_value(frm.doctype, frm.doc.name, "ph_service_servicefall", r.message).then(() => frappe.set_route("Form", "PH Servicefall", r.message));
				});
			}, __("Servicefall aus Wareneingang"));
		}, __("Aktionen"));
	},
});

frappe.ui.form.on("PH Lieferschein", {
	refresh(frm) {
		if (frm.is_new()) return;
		frm.add_custom_button(__("Servicefall anlegen"), () => {
			frappe.prompt([
				{ fieldname: "art", fieldtype: "Select", label: __("Art"), options: ["Transportschaden", "Mangel"], default: "Transportschaden", reqd: 1 },
				{ fieldname: "produkt", fieldtype: "Link", options: "PH Produkt", label: __("Produkt") },
				{ fieldname: "beschreibung", fieldtype: "Small Text", label: __("Beschreibung"), reqd: 1 },
			], (v) => {
				frappe.call({ method: "ph_service.ph_service.doctype.ph_servicefall.ph_servicefall.aus_dokument", args: { doctype: frm.doctype, name: frm.doc.name, ...v }, freeze: true }).then((r) => r.message && frappe.set_route("Form", "PH Servicefall", r.message));
			}, __("Servicefall aus Lieferschein"));
		}, __("Aktionen"));
	},
});
